from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1]
data=json.loads((ROOT/'kaynak/manifest.json').read_text())
by={i['size']:i for i in data}
names={'300x250':'Orta dikdörtgen','336x280':'Büyük dikdörtgen','728x90':'Leaderboard','970x250':'Billboard','300x600':'Yarım sayfa','160x600':'Geniş gökdelen','320x50':'Mobil banner','1080x1080':'Sosyal kare','1080x1920':'Hikâye','1200x628':'Sosyal yatay'}
def card(key,span,stage_h=None):
 i=by[key];w=i['width'];h=i['height'];ani=i['animated'];size=(ROOT/'png'/f'{key}.png').stat().st_size
 return f'''<article class="card span-{span}" data-size="{key}" data-w="{w}" data-h="{h}">
 <div class="card-head"><div><h3>{w} × {h}</h3><span>{names[key]}</span></div><span class="tag">{'PNG + HTML5' if ani else 'PNG'}</span></div>
 <div class="stage" {'style="min-height:'+str(stage_h)+'px"' if stage_h else ''}><div class="frame" style="width:{w}px;aspect-ratio:{w}/{h}"><img src="png/{key}.png" width="{w}" height="{h}" alt="Demlik Demini Al — {names[key]}, {w}×{h}">{'<iframe title="'+key+' hareketli reklam" data-src="html5/'+key+'/index.html" width="'+str(w)+'" height="'+str(h)+'" tabindex="-1"></iframe>' if ani else ''}</div></div>
 <div class="card-foot"><a href="png/{key}.png" download>PNG indir <span>↗</span></a><span class="weight">{size/1024:.0f} KB</span>{'<a href="html5/'+key+'.zip" download title="Bağımsız HTML5 reklam paketi">ZIP ↓</a><button type="button" class="motion-toggle" aria-pressed="false">▶ Hareketli izle</button>' if ani else '<a class="source" href="kaynak/svg/'+key+'.svg" target="_blank">SVG aç ↗</a>'}</div></article>'''
page='''<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Demlik — Demini Al / Kampanya seti</title>
<style>
:root{--paper:#f4ecd9;--ink:#49241f;--orange:#cc5835;--line:#dcd2bf;--muted:#776b60}*{box-sizing:border-box}body{margin:0;background:#f7f4ed;color:var(--ink);font-family:Arial,Helvetica,sans-serif}button,a{-webkit-tap-highlight-color:transparent}button{font:inherit}a{color:inherit;text-decoration:none}a:focus-visible,button:focus-visible{outline:3px solid var(--orange);outline-offset:4px}header{background:var(--paper);border-bottom:1px solid var(--line)}.wrap{max-width:1296px;padding:0 48px;margin:auto}.top{height:100px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #49241f30}.wordmark{font-family:'URW Bookman',Georgia,serif;font-weight:900;font-size:36px;letter-spacing:-2.5px}.wordmark b{color:var(--orange)}.eyebrow{font-size:11px;font-weight:700;letter-spacing:2px;line-height:1.8;text-transform:uppercase}.top .eyebrow{text-align:right}.intro{padding:66px 0 60px;display:grid;grid-template-columns:1.45fr 1fr;gap:70px;align-items:end}.intro h1{font-family:'URW Bookman',Georgia,serif;font-size:clamp(54px,6.6vw,87px);line-height:1.06;letter-spacing:-5px;margin:16px 0 0;font-weight:900}.intro h1 em{color:var(--orange)}.intro p{font-size:16px;line-height:1.7;margin:0 0 28px;max-width:410px}.specs{display:flex;gap:24px;border-top:1px solid #49241f30;padding-top:22px}.specs b{display:block;font-size:25px;font-family:Georgia,serif}.specs span{font-size:10px;text-transform:uppercase;letter-spacing:1.4px;display:block;margin-top:7px}.toolbar{position:sticky;top:0;z-index:20;backdrop-filter:blur(12px);background:#f7f4edef;border-bottom:1px solid var(--line)}.toolbar .wrap{min-height:72px;display:flex;align-items:center;justify-content:space-between;gap:15px}.tabs{display:flex;gap:6px}.tabs a,.controls button{font-size:12px;border:1px solid var(--line);padding:10px 17px;background:transparent;border-radius:30px;cursor:pointer}.tabs a:hover,.controls button:hover{background:var(--paper)}.tabs a:first-child{background:var(--ink);color:var(--paper);border-color:var(--ink)}.controls{display:flex;align-items:center;gap:14px}.controls small{font-size:11px;color:var(--muted)}main{padding-top:52px!important}.section-label{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:24px;scroll-margin-top:100px}.section-label h2{font-size:23px;letter-spacing:-.8px;margin:0}.section-label h2 span{font-size:11px;letter-spacing:1px;color:var(--orange);margin-right:12px;vertical-align:middle}.section-label p{font-size:12px;color:var(--muted)}.grid{display:grid;grid-template-columns:repeat(12,minmax(0,1fr));gap:22px;margin-bottom:56px;align-items:start}.span-12{grid-column:span 12}.span-6{grid-column:span 6}.span-4{grid-column:span 4}.card{border:1px solid var(--line);background:#fffdf8;border-radius:6px;overflow:hidden}.card-head{padding:19px 22px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line);gap:10px}.card-head h3{margin:0 0 5px;font-size:17px;letter-spacing:.3px}.card-head div>span{font-size:11px;color:var(--muted)}.tag{font-size:9px;border:1px solid var(--line);padding:6px 8px;border-radius:3px;letter-spacing:.5px;white-space:nowrap}.stage{padding:30px 22px;background:#e9e4d9;display:flex;justify-content:center;align-items:center;overflow:hidden}.frame{position:relative;max-width:100%;flex:none;box-shadow:0 3px 12px #49241f0d}.frame img{display:block;width:100%;height:auto}.frame iframe{position:absolute;top:0;left:0;border:0;transform-origin:0 0;display:none;background:var(--paper);max-width:none}.card.playing iframe{display:block}.card.playing img{visibility:hidden}.card-foot{display:flex;align-items:center;gap:12px;padding:15px 22px;min-height:56px;font-size:11px}.card-foot>a:first-child{font-weight:700}.card-foot a:hover{text-decoration:underline;text-underline-offset:4px}.weight{color:var(--muted);font-size:10px}.motion-toggle,.source{margin-left:auto}.motion-toggle{border:0;color:var(--ink);background:none;padding:6px 0 6px 10px;font-size:11px;font-weight:700;cursor:pointer}.playing .motion-toggle{color:var(--orange)}.notes{border-top:1px solid var(--line);display:grid;grid-template-columns:1fr 1fr 1fr;gap:45px;padding:38px 0 50px}.notes h3{font-size:13px}.notes p{font-size:12px;line-height:1.7;color:var(--muted)}.notes a{text-decoration:underline;text-underline-offset:3px}footer{border-top:1px solid var(--line);background:var(--ink);color:var(--paper)}footer .wrap{padding-top:25px;padding-bottom:25px;display:flex;justify-content:space-between;font-size:11px;gap:20px}#toast{position:fixed;bottom:25px;left:50%;transform:translateX(-50%);border-radius:30px;background:var(--ink);color:var(--paper);padding:13px 24px;font-size:12px;z-index:50;box-shadow:0 4px 15px #0002;display:none}
@media(min-width:1000px){.card[data-size="300x250"] .stage,.card[data-size="336x280"] .stage,.card[data-size="320x50"] .stage{height:340px}.card[data-size="300x600"] .stage,.card[data-size="160x600"] .stage{height:650px}}
@media(max-width:900px){.wrap{padding:0 24px}.intro{gap:30px}.intro h1{letter-spacing:-3px}.controls small{display:none}.span-4{grid-column:span 6}.card[data-size="320x50"]{grid-column:span 12}.card-head{padding:15px}.card-foot{padding:12px 15px}.stage{padding:22px 15px}.notes{gap:24px}.tag{font-size:8px}.intro p{font-size:14px}}
@media(max-width:600px){.wrap{padding:0 18px}.top{height:80px}.wordmark{font-size:30px}.top .eyebrow{font-size:8px;letter-spacing:1px}.intro{padding:38px 0;grid-template-columns:1fr;gap:30px}.intro h1{font-size:58px}.intro p{font-size:14px;max-width:none;margin-bottom:20px}.specs{gap:36px}.toolbar .wrap{min-height:66px;gap:8px}.tabs a,.controls button{font-size:10px;padding:9px 11px}.controls{gap:0}.section-label{align-items:start;flex-direction:column;gap:0}.section-label p{margin:10px 0 0}.grid{gap:18px}.span-4,.span-6,.span-12{grid-column:span 12}.notes{grid-template-columns:1fr;gap:12px}.notes h3{margin-bottom:5px}.notes p{margin-top:0}.card-head{padding:17px}.card-foot{padding:13px 17px}footer .wrap{flex-direction:column;gap:9px}}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}
</style></head><body>
<header id="top"><div class="wrap"><div class="top"><a class="wordmark" href="#top" aria-label="Demlik">demlik<b>·</b></a><div class="eyebrow">Ekim kampanyası<br>Dijital reklam koleksiyonu</div></div><div class="intro"><div><div class="eyebrow">Kadıköy Akşamı / Yeni sonbahar harmanı</div><h1>Akşamın<br><em>ince belli hâli.</em></h1></div><div><p>Şehrin acelesine küçük bir çay molası.<br><strong>Demini Al</strong>, akşam güneşini ince belli bir bardağa taşıyor. Tek fikir; her mecrada kendi ritmi.</p><div class="specs"><div><b>10</b><span>PNG boyutu</span></div><div><b>05</b><span>HTML5 reklam</span></div><div><b>13,2 sn</b><span>Hareket süresi</span></div></div></div></div></div></header>
<nav class="toolbar" aria-label="Önizleme kontrolleri"><div class="wrap"><div class="tabs"><a href="#display">Display / 7</a><a href="#social">Sosyal / 3</a></div><div class="controls"><small>Gerçek dosyalar · Ölçeğe göre önizleme</small><button id="allMotion" type="button" aria-pressed="false">▶ Tüm hareketliler</button></div></div></nav>
<main class="wrap"><div class="section-label" id="display"><h2><span>01</span> Display reklamları</h2><p>Küçük bir alanda, büyük bir mola.</p></div><div class="grid">
'''
for key,span,hh in [('300x250',4,None),('336x280',4,None),('320x50',4,None),('970x250',12,None),('728x90',12,None),('300x600',6,None),('160x600',6,None)]:page+=card(key,span,hh)
page+='''</div><div class="section-label" id="social"><h2><span>02</span> Sosyal medya</h2><p>Kare, hikâye ve yatay. Aynı akşamın üç hâli.</p></div><div class="grid">'''
for key,span in [('1080x1080',6),('1080x1920',6),('1200x628',12)]:page+=card(key,span)
page+='''</div><section class="notes" aria-label="Teslim bilgileri"><div><h3>Tek dosyada çalışan HTML5</h3><p>Harici font, görsel veya kütüphane isteği yok. Beş boyut için <code>clickTag</code> destekli bağımsız reklamlar ve yüklemeye hazır ZIP paketleri. <a href="html5/index.html">HTML5 klasörü ↗</a></p></div><div><h3>Hareketin de bir demlenme süresi var.</h3><p>Güneş açılır, bardak yerleşir, buhar yavaşça yükselir. 13,2 saniyede durur. Azaltılmış hareket tercihi otomatik uygulanır. Yeniden izlemek için ilgili önizlemeyi kapatıp açın.</p></div><div><h3>Tamamı kodla çizildi.</h3><p>Özgün SVG bardak illüstrasyonu, vektör yazılar ve boyuta özel kompozisyonlar. PNG dosyaları doğal çözünürlükte. <a href="TESLIM.md">Teslim ve kullanım notları ↗</a></p></div></section></main><footer><div class="wrap"><span>demlik · Demini Al / Ekim</span><span>Kurgu marka · Moda Cd. No: 42, Kadıköy · demlik.com.tr</span></div></footer><div id="toast" role="status"></div>
<script>
const cards=[...document.querySelectorAll('.card')];
function fit(card){const frame=card.querySelector('.frame'),iframe=card.querySelector('iframe');if(iframe)iframe.style.transform='scale('+frame.clientWidth/Number(card.dataset.w)+')';}
function motion(card,on){const iframe=card.querySelector('iframe');if(!iframe)return;card.classList.toggle('playing',on);const button=card.querySelector('.motion-toggle');button.textContent=on?'■ PNG’ye dön':'▶ Hareketli izle';button.setAttribute('aria-pressed',String(on));if(on){iframe.src=iframe.dataset.src;iframe.tabIndex=0;}else{iframe.removeAttribute('src');iframe.tabIndex=-1;}fit(card);}
const observer=new ResizeObserver(entries=>entries.forEach(e=>fit(e.target)));cards.forEach(card=>{observer.observe(card);card.querySelector('.motion-toggle')?.addEventListener('click',()=>{motion(card,!card.classList.contains('playing'));sync();});});
function sync(){const on=cards.some(c=>c.classList.contains('playing'));document.getElementById('allMotion').setAttribute('aria-pressed',String(on));document.getElementById('allMotion').textContent=on?'■ Tüm PNG’lere dön':'▶ Tüm hareketliler';}
document.getElementById('allMotion').addEventListener('click',()=>{const on=!cards.some(c=>c.classList.contains('playing'));cards.forEach(c=>motion(c,on));sync();});
</script></body></html>'''
(ROOT/'onizleme.html').write_text(page)
print('onizleme.html hazır')
